#define FOV 		60.0
const float text[] = float[21](72., 97., 112., 112., 121., 32., 86., 97., 108., 101., 110., 116., 105., 110., 101., 115., 32., 100., 97., 121., 33. );

#define RED     vec3( 1,.8,.8)

const float MINIMUM_HIT_DISTANCE = 0.0001;

float opSmoothUnion( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

float sdChar(vec3 p, float i, float depth) {    

    float ix = floor(mod(i, 16.));
    float iy = floor(i / 16.);   


    vec2 pxy = clamp(p.xy * 0.5 + 0.5, 0., 1.);
    pxy /= 16.0;
    pxy += vec2(ix, 15. - iy) / 16.0;    

    float dxy = texture(iChannel0, pxy).a * 2. - 1.;        
    float dz = abs(p.z) - depth * .5;

    float sig = (dxy < 0. && dz < 0.) ? -1. : 1.;
    dxy = max(dxy, 0.);
    dz = max(dz, 0.);


    float d = sqrt(dxy*dxy + dz*dz) * sig;    
    return d - 0.03;
}


float displacement(vec3 p){
    //return 0.2*sin(iTime*PI*3.);

    float T = mod(iTime * PI*2., PI*2.);
    float H = clamp(.5 * sin(T) * sin(T / 2.) * exp(-T / 4.) + .5, 0., 1.);
    return -1.*H;

    //vec2 uv = fragCoord.xy / iResolution.xy;

    // the sound texture is 512x2 
	// first row is frequency data (48Khz/4 in 512 texels, meaning 23 Hz per texel)
	//float fft  = texture( iChannel2, vec2(0,0)).x; 
    //return -0.5*fft;


}

float sdEllipsoid( vec3 p, vec3 r ,vec3 p2)
{
  float k0 = length(p/r);
  float k1 = length(p/(r*r));
  return k0*(k0-1.0)/k1 + displacement(p2);
}

float sdHeart(vec3 p, float s){
    float a = PI*0.333;
    mat3 rot1 = mat3(sin(a),cos(a),0,
                     -cos(a),sin(a),0,
                     0,0,1);
     mat3 rot2 = mat3(sin(-a),cos(-a),0,
                     -cos(-a),sin(-a),0,
                     0,0,1);
    vec3 q1 = rot1*(vec3(s*0.333,0,0)-p);
    vec3 q2 = rot2*(vec3(s*-0.333,0,0)-p);
    return opSmoothUnion(sdEllipsoid(q1,vec3(s,s*1.5,s*0.75),p),sdEllipsoid(q2,vec3(s,s*1.5,s*0.75),p),0.3);
}



vec4 skyColor(in vec3 ro, in vec3 rd){
    return texture(iChannel1, normalize(rd))*vec4(1.5,0.75,0.75,1);
}


float map_the_world(in vec3 p){

    float m = sdHeart(p,2.0);
    float scaleText = 2.;
    for(int i=0; i< 21; i++){
        vec3 q = (p-vec3((float(i)-9.)/scaleText,5,0))*scaleText;
        m = min(m,sdChar(q,text[i],0.125)/scaleText);
    }
    return m;

}


vec3 calculate_normal(in vec3 p){
    const vec3 small_step = vec3(0.00001, 0.0, 0.0);
    float gradient_x = map_the_world(p + small_step.xyy) - map_the_world(p - small_step.xyy);
    float gradient_y = map_the_world(p + small_step.yxy) - map_the_world(p - small_step.yxy);
    float gradient_z = map_the_world(p + small_step.yyx) - map_the_world(p - small_step.yyx);
    vec3 normal = vec3(gradient_x, gradient_y, gradient_z);
    return normalize(normal);
}

vec3 brdf(vec3 N, vec3 L, vec3 V, vec3 diff, vec3 spec, float exponent) {
    vec3 R = reflect(L,N);
    vec3 H = normalize(L+V);
    return diff * clamp(dot(N, L), 0., 1.)
         + spec * pow(max(0., dot(R,V)), exponent);
}

vec3 shade(vec3 P, vec3 N, vec3 ro) {
    vec3 V = normalize(P-ro);
    vec3 ambient = vec3(0.3,0.1,0.1);
    vec3 diffuse = vec3(.9, .1, .1);
    vec3 specular = vec3(1.0, .7, 0.7);
    vec3 light1 = brdf(N, normalize(vec3(1,1,1) - P), V, diffuse, specular, 16.);
    vec3 light2 = brdf(N, normalize(vec3(-1,0,-0.5) - P), V, diffuse, specular, 16.);
    return ambient + light1 + light2;
}

vec4 ray_march(in vec3 ro, in vec3 rd){
    const int NUMBER_OF_STEPS = 32;   
    const float MAXIMUM_TRACE_DISTANCE = 15.0;
    vec3 current_position = ro;
    float total_distance_traveled = 0.;
    for (int i = 0; i < NUMBER_OF_STEPS; ++i)
    {
        float distance_to_closest = map_the_world(current_position);
        current_position += rd*distance_to_closest;
        total_distance_traveled+=distance_to_closest;

        if (distance_to_closest < MINIMUM_HIT_DISTANCE) 
        {    
            vec3 normal = calculate_normal(current_position);
            return vec4(shade(rd, normal, current_position),1.0);
        }
        if (total_distance_traveled > MAXIMUM_TRACE_DISTANCE )
        {
            break;
        } 
    }
    return skyColor(ro,rd);
}

vec4 samplePixel(in vec2 fragCoord){
    float a = mod(0.125*sin(-iTime*+0.3) +(iMouse.x/iResolution.x-0.5),PI*2.);
    vec2 uv = (2.*(fragCoord.xy)/iResolution.y-1.) * tan (radians (FOV)/2.0);
	float b = mod(-PI/16.0+0.05*sin(iTime*0.321)+iMouse.y*PI*0.25/iResolution.y-0.2,PI*2.);
    float bs = sin(b);
    float bc = cos(b);
    float as = sin(a);
    float ac = cos(a);
    vec3 fw = vec3 (bc*as, bs, bc*ac);			// forward
    vec3 lf = vec3(ac,0, -as);
    vec3 up = normalize(cross(fw,lf));
	vec3 ro = 10.*vec3(-bc*as,-bs+0.125+0.125,-bc*ac); // ray origin
	vec3 rd = normalize ((uv.x-.5) * lf + uv.y * up +fw) ; 		// ray direction
    vec4 march = ray_march(ro,rd);
    return vec4(march.xyz,1.0);
}

vec4 superSamplePixel(in vec2 fragCoord){
    vec2 step = vec2(.5);
    vec4 sum=vec4(0);
    for(int i=0;i<2;i++){
        for(int j=0; j<2;j++){
            sum+=samplePixel(fragCoord+vec2(i,j)*step);
        }
    }
    return sum*0.25;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    fragColor= samplePixel(fragCoord);

}
